//! Write a synthetic payload of scrolling text in which many cells carry
//! combining marks, for the `frame` bench's marked-cell rows: the
//! `gen-marks-payload` example.
//!
//! ```text
//! cargo run -p baud-bench --example gen-marks-payload -- marks target/marks.raw
//! cargo run -p baud-bench --example gen-marks-payload -- covered target/marks-covered.raw
//! cargo bench -p baud-bench --bench frame -- ../../target/marks.raw 5
//! ```
//!
//! (`frame` reads its recording relative to `tools/tests/recordings/`, and `target/`
//! keeps the generated bytes out of the tree.)
//!
//! **It is synthetic, and a number from it is a claim about marked cells, not
//! about a session.** No recording in `tools/tests/recordings/` carries marks densely
//! enough to price the per-cluster face choice: cat-cjk and vim-unicode have a
//! few dozen marked cells. So this prices the marked path and nothing else, the
//! way `payload::cjk` prices wide text.
//!
//! The seed is fixed, so every run writes the same bytes: about 1 MiB, lines of
//! 120 to 199 columns, 15% spaces. Per letter (from `aeiouqwxnrst`):
//!
//! * `marks`: 60% bare; 12% + U+0301 (acute: composes on a vowel, a mark glyph
//!   on q, w and x); 10% + U+0323 (dot below); 6% + U+0301 + U+0323; 4% +
//!   U+0305 (JetBrains Mono lacks it, Fira Code has it); 3% q + U+0316 + U+0301
//!   (no test face has U+0316); 2% + U+0305 + U+0309 (JetBrains Mono lacks
//!   U+0305, Fira Code lacks U+0309); 3% + U+0301 + U+200D (an ignorable rides
//!   along).
//! * `covered`: the same draws, with only the marks JetBrains Mono has: 60%
//!   bare, 12% + U+0301, 10% + U+0323, 18% + U+0301 + U+0323. So no cluster
//!   is moved or dropped, and the row prices the coverage test alone.
//!
//! Both share one random sequence (a draw per letter decides its marks whatever
//! the mix), so `covered` is `marks` with the uncovered marks replaced.

use std::ffi::OsString;

use super::draws::Draws;
use super::py;

const LETTERS: &[char] = &['a', 'e', 'i', 'o', 'u', 'q', 'w', 'x', 'n', 'r', 's', 't'];
const SEED: u32 = 20_261_007;

/// What follows a letter drawn below a bound.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum After {
    /// These marks, on the letter drawn.
    Marks(&'static str),
    /// q + U+0316 + U+0301, in place of the letter drawn.
    Replaced,
}

/// A mix: each upper bound of the draw and what it gives.
type Mix = &'static [(f64, After)];

const MARKS: Mix = &[
    (0.60, After::Marks("")),
    (0.72, After::Marks("\u{301}")),
    (0.82, After::Marks("\u{323}")),
    (0.88, After::Marks("\u{301}\u{323}")),
    (0.92, After::Marks("\u{305}")),
    (0.95, After::Replaced),
    (0.97, After::Marks("\u{305}\u{309}")),
    (1.00, After::Marks("\u{301}\u{200d}")),
];

const COVERED: Mix = &[
    (0.60, After::Marks("")),
    (0.72, After::Marks("\u{301}")),
    (0.82, After::Marks("\u{323}")),
    (1.00, After::Marks("\u{301}\u{323}")),
];

fn mix_named(name: &str) -> Option<Mix> {
    match name {
        "marks" => Some(MARKS),
        "covered" => Some(COVERED),
        _ => None,
    }
}

/// One cell: a letter and what the draw put on it.
fn cell(mix: Mix, rng: &mut Draws, line: &mut String) {
    let base = *rng.choice(LETTERS);
    let r = rng.random();
    for (bound, after) in mix {
        if r < *bound {
            match after {
                After::Marks(m) => {
                    line.push(base);
                    line.push_str(m);
                }
                After::Replaced => line.push_str("q\u{316}\u{301}"),
            }
            return;
        }
    }
    line.push(base);
}

/// The payload of the named mix, at least `target` bytes, and its line count.
pub fn generate(name: &str, target: i64) -> Option<(Vec<u8>, usize)> {
    let mix = mix_named(name)?;
    let mut rng = Draws::new(SEED);
    let mut out = Vec::new();
    let mut lines = 0;
    while i64::try_from(out.len()).unwrap_or(i64::MAX) < target {
        let cols = rng.randint(120, 199);
        let mut line = String::new();
        for _ in 0..cols {
            if rng.random() < 0.15 {
                line.push(' ');
            } else {
                cell(mix, &mut rng, &mut line);
            }
        }
        line.push_str("\r\n");
        out.extend_from_slice(line.as_bytes());
        lines += 1;
    }
    Some((out, lines))
}

/// The example.
pub fn run(args: &[OsString]) -> i32 {
    let name = args.first().map(|a| a.to_string_lossy().into_owned());
    let known = name.as_deref().is_some_and(|n| mix_named(n).is_some());
    if !(args.len() == 2 || args.len() == 3) || !known {
        return super::died("usage: gen-marks-payload {marks|covered} OUT [BYTES]");
    }
    let name = name.expect("checked above");
    let target = match args.get(2) {
        None => 1 << 20,
        Some(b) => match py::int(&b.to_string_lossy()) {
            Some(v) => v,
            None => {
                return super::died(&format!(
                    "invalid literal for int() with base 10: {}",
                    py::str_repr(&b.to_string_lossy())
                ));
            }
        },
    };
    let (out, lines) = generate(&name, target).expect("a known mix");
    if let Err(e) = std::fs::write(&args[1], &out) {
        return super::died(&format!("open: {e}"));
    }
    println!("{} bytes, {lines} lines", out.len());
    0
}
